for(i in 1:length(object.list)) {
    object.list[[i]][['percent.mt']] <- PercentageFeatureSet(object.list[[i]], pattern = '^MT-')
    object.list[[i]] <- PercentageFeatureSet(object.list[[i]], pattern = '^RPS', col.name = 'percent.rps')
    object.list[[i]] <- PercentageFeatureSet(object.list[[i]], pattern = '^RPL', col.name = 'percent.rpl')
    object.list[[i]]$percent.rp <- object.list[[i]]$percent.rps + object.list[[i]]$percent.rpl
}
# Annotate patient info
for(i in 1:length(object.list)) {
    object.list[[i]][['patient']] <- pat_list[[i]]
}

for(i in 1:length(object.list)) {
    pat <- pat_list[[i]]
    print(paste0("[", pat, "] num cells: ", length(Cells(object.list[[i]]))))
}

for(i in 1:length(object.list)) {
    object.list[[i]][['celltype_initial_singleR']] <- pred.list[[i]]$labels
    saveRDS(object.list[[i]], file = paste0('data/', pat_list[[i]], '/data_', pat_list[[i]], '_cb_raw_singler.rds'))
}
